import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.IOException;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int left = in.nextInt() - 1;
            int right = in.nextInt() - 1;
            int period = a + b;
            int[] arr = new int[period * 4];

            int shift = left / period;
            left -= shift * period;
            right -= shift * period;
            shift = (right - left + 1) / period;
            if (shift > 2) {
                right -= (shift - 2) * period;
            }

            int d = a > b ? a - b : 1;

            for (int block = 0; block < 4; block++) {
                int base = period * block;
                for (int pos = 0; pos < a; pos++) {
                    if ((block & 1) == 1 && pos >= a - d) {
                        arr[base + pos] = pos + d;
                    } else {
                        arr[base + pos] = pos;
                    }
                }
            }

            int min = a + a;
            for (int k0 = 1; k0 <= d; k0++) {
                for (int k = 0; k < b; k++) {
                    arr[a + k] = arr[a - k0];
                }
                for (int k1 = 1; k1 <= d; k1++) {
                    for (int k = 0; k < b; k++) {
                        arr[period + a + k] = arr[period + a - k1];
                    }
                    for (int k2 = 1; k2 <= d; k2++) {
                        for (int k = 0; k < b; k++) {
                            arr[2 * period + a + k] = arr[2 * period + a - k2];
                        }
                        for (int k3 = 1; k3 <= d; k3++) {
                            for (int k = 0; k < b; k++) {
                                arr[3 * period + a + k] = arr[3 * period + a - k3];
                            }
                            min = Math.min(min, count(arr, left, right));
                        }
                    }
                }
            }
            out.println(min);
        }

        static int count(int[] arr, int l, int r) {
            boolean[] seen = new boolean[24];
            int cnt = 0;
            for (int i = l; i <= r; i++) {
                int c = arr[i];
                if (!seen[c]) {
                    seen[c] = true;
                    cnt++;
                }
            }
            return cnt;
        }
    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = read();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
